close all
clearvars -except mapCD
fn = 'D:\od\OneDrive\matlab\RawData\1T-TaS2(point defect)\mapCD.mat';
loadif(fn); %[output:20ea1dd8] %[output:7f55cad5]

%%
%[text] ## Masked FFT filter
%[text] ### Create FFT mask
%[text] for iph = 1
iph = 1 %[output:9de9b51b]
mskTbl =table() %[output:6b268df2]

Z = mapCD.dt(iph).Z;
fZ = fft2(Z);
afZ = abs(fZ);

% mskTbl =table()
bin = afZ> 0.001*max(max(afZ)) %[output:2597c12c]
mskTbl = {bin,'2nd order peak visible histogram cut','too many aperiodic '} %[output:124518ec]
mskTbl(2,:) = {R4fft(size(Z))>35,'kill low freq 35','still aperiodic term but better than 1st one'} %[output:5614d0db]
mskTbl(3,:) = {R4fft(size(Z))<130 'kill hi freq 1130' 'Maybe I focus on more than 2nd order peak, but high frequency does not affect to the result'} %[output:12e44f0b]
mskTbl(4,:) = {mskTbl{2,1} & mskTbl{3,1},'ref 2,3 kill hi low','.'} %[output:95cb4bf4]
mskTbl(5,:) = {mskTbl{4,1}&mskTbl{1,1},'1 bas kill hi low','.'} %[output:5432bba2]
%%
%[text] for iph = 2
iph = 2 %[output:777eab90]
mskTbl =table() %[output:6353d625]

Z = mapCD.dt(iph).Z;
fZ = fft2(Z);
afZ = abs(fZ);

% mskTbl =table()
bin = afZ> 0.001*max(max(afZ)) %[output:88a91e5f]
mskTbl = {bin,'2nd order peak visible histogram cut','too many aperiodic '} %[output:3398e94d]
%%
 
%%
%[text] ## Draw filtered result
groot().Children %[output:4b7d46b6]
%[text] Main function
msk = mskTbl(1,:) %[output:156ab959]
bin = msk{1};
[f,sbs] =  plt_Fourier_filtered_synthesis(Z,bin) %[output:35fc3007] %[output:86ac0592] %[output:54b7f010] %[output:1b7814fd] %[output:3cd1b436] %[output:737636f8] %[output:3565bb6b] %[output:88fdc8c1] %[output:93855cc4] %[output:970777f0] %[output:99869e67] %[output:079c9510] %[output:1f0d2e1e] %[output:891a069a] %[output:5c03f68f] %[output:08d4d0be] %[output:8c9d9e06]
f.Visible = "on" %[output:4cec7ada] %[output:8c9d9e06]
f.Position = [0 0 2000 1000] %[output:031bc7d0] %[output:8c9d9e06]
%[text] colorlim modification
f.CurrentAxes = sbs(1,2) %[output:7c3e6037]
climsc([0, 0.01]).Minmax %[output:4b65b1e3] %[output:8c9d9e06]
sbs(2,3).CLim = sbs(1,2).CLim %[output:8c9d9e06] %[output:65dcd9e5]
%%
se = strel('disk',2) %[output:53c3fbaf]
views(se.Neighborhood) %[output:4e168d46]
%[text] 4 or 5 mask filter
%%
%[text] ### 
%[text] 
function titlet(str)
title(str)
ax = gca;
ax.Tag = str;
end
%[text] 
function viewst(img)
views(fftshift(img))
end
%[text] 
function popViewst(bin)
f = figure(10)
views(fftshift(bin))
f.Visible = "on"
end


